// Same rules as inbound.py, kept deliberately small.
const lead = $json.body || {};
const email = String(lead.email || '').trim().toLowerCase();
const valid = /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(email) && !!lead.form_id;
const domain = email.split('@')[1] || '';
const free = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'aol.com', 'proton.me'].includes(domain);
const formPoints = { demo_request: 45, pricing: 25, contact: 15, newsletter: 0 }[lead.form_id] ?? 5;
const sizePoints = { '1000+': 30, '200-999': 20, '50-199': 10 }[lead.company_size] ?? 0;
const senior = /\b(ceo|cro|chief|founder|vp|vice president|head|director)\b/i.test(lead.title || '');
const score = !valid || free ? 0 : Math.min(100, formPoints + sizePoints + (senior ? 15 : 0));
const owner = score >= 70 ? 'ae_queue' : score >= 40 ? 'sdr_queue' : 'nurture';
return { json: { email, domain, form_id: lead.form_id, title: lead.title || '', company: lead.company || '', company_size: lead.company_size || '', valid, free_email: free, score, owner } };
